import os
import torch


class Config:
    """
    Configuration class for the Deep Parallel Vector-DCN-ResNet pipeline.
    """

    # -------------------------------------------------------------------------
    # Reproducibility
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # Paths
    # -------------------------------------------------------------------------
    # Metadata paths (Parquet files generated by metadata script)
    METADATA_DIR = "./metadata"
    TRAIN_DATA_PATH = os.path.join(METADATA_DIR, "train.parquet")
    VAL_DATA_PATH = os.path.join(METADATA_DIR, "val.parquet")
    TEST_DATA_PATH = os.path.join(METADATA_DIR, "test.parquet")

    # Working directory for checkpoints, cache, and temporary files
    WORKING_DIR = "./working/idea_23"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")

    # Submission output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Model Checkpoint
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # -------------------------------------------------------------------------
    # Data Configuration
    # -------------------------------------------------------------------------
    ID_COL = "Id"
    TARGET_COL = "Cover_Type"

    # -------------------------------------------------------------------------
    # Model Architecture Hyperparameters
    # -------------------------------------------------------------------------
    # Deep Parallel Vector-DCN-ResNet
    HIDDEN_DIM = 512  # Width of the ResNet blocks and DCN layers
    NUM_RES_BLOCKS = 4  # Depth of the ResNet backbone
    DROPOUT_RATE = 0.2  # Regularization within blocks

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    BATCH_SIZE = 4096
    EPOCHS = 60
    LEARNING_RATE = 1e-3  # Initial learning rate
    WEIGHT_DECAY = 1e-2  # Decoupled weight decay for AdamW

    # Scheduler (ReduceLROnPlateau)
    SCHEDULER_FACTOR = 0.1
    SCHEDULER_PATIENCE = 5
    EARLY_STOPPING_PATIENCE = 10

    # -------------------------------------------------------------------------
    # Runtime / Hardware
    # -------------------------------------------------------------------------
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Debugging flags
    DEBUG = False  # Set to True to run with a smaller subset
    DEBUG_SAMPLES = 10000  # Number of samples to use in debug mode

    @classmethod
    def create_directories(cls):
        """Creates the necessary directories for the project."""
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
